package in.finseq.insurance;
import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.text.*;import java.util.*;
public class AttendanceCalendarActivity extends FinseqActivity{
 LinearLayout body,list;EditText month;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=Ui.column(this);Ui.appHeader(root,this,"Attendance Calendar");body=Ui.contentColumn(this);root.addView(body);month=Ui.input(this,"YYYY-MM");month.setText(new SimpleDateFormat("yyyy-MM",Locale.US).format(new Date()));Button load=Ui.greenButton(this,"Load Month");load.setOnClickListener(v->load());body.addView(month);body.addView(load);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);body.addView(list);Ui.setScreen(this,root,5);load();}
 void load(){final String m=month.getText().toString().trim();list.removeAllViews();list.addView(Ui.sub(this,"Loading…"));Ui.run(this,()->{try{JSONObject j=ApiClient.get(this,"/api/attendance/history?month="+m);JSONArray a=j.optJSONArray("records"),h=j.optJSONArray("holidays"),l=j.optJSONArray("leaves");Ui.ui(this,()->{list.removeAllViews();TextView s=Ui.sub(this,"Records: "+(a==null?0:a.length())+" · Holidays: "+(h==null?0:h.length())+" · Leave requests: "+(l==null?0:l.length()));list.addView(s);if(a!=null)for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);LinearLayout c=Ui.card(this);c.addView(Ui.text(this,x.optString("work_date")+" · "+x.optString("status"),17,true));c.addView(Ui.sub(this,"In: "+AttendanceActivity.time(x.optString("check_in"))+"   Out: "+AttendanceActivity.time(x.optString("check_out"))+"\nLate: "+x.optInt("late_minutes")+" min · Work: "+x.optInt("work_minutes")+" min"));list.addView(c);}if(a==null||a.length()==0)list.addView(Ui.sub(this,"No attendance records for this month."));});}catch(Exception e){Ui.ui(this,()->{list.removeAllViews();list.addView(Ui.sub(this,e.getMessage()));});}});}
}